/**
 * AnalyticsDashboard - 数据分析仪表盘
 * 使用统计 + 热力图 + 趋势分析
 */
import { getUsageStats } from './PerformanceOptimizer.js';

// 存储键
const ANALYTICS_KEY = 'ai-creator-analytics';
const EVENTS_KEY = 'ai-creator-events';

// 事件类型
export const EventType = {
  PAGE_VIEW: 'page_view',
  TOOL_USE: 'tool_use',
  TOOL_CREATE: 'tool_create',
  TOOL_EDIT: 'tool_edit',
  TOOL_DELETE: 'tool_delete',
  WORKFLOW_RUN: 'workflow_run',
  SEARCH: 'search',
  FILTER: 'filter',
  ERROR: 'error'
};

// 初始化
export function initAnalytics() {
  // 恢复事件数据
  restoreEvents();
  
  // 定期清理旧数据（保留30天）
  setInterval(cleanOldEvents, 24 * 60 * 60 * 1000);
  
  console.log('[Analytics] Initialized');
}

// ============ 事件追踪 ============

/**
 * 记录事件
 */
export function trackEvent(type, data = {}) {
  const event = {
    id: 'evt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
    type,
    data,
    timestamp: Date.now(),
    sessionId: getSessionId()
  };
  
  const events = getEvents();
  events.push(event);
  
  // 限制事件数量（保留最近10000条）
  const trimmed = events.slice(-10000);
  saveEvents(trimmed);
  
  return event;
}

/**
 * 获取事件列表
 */
export function getEvents(limit = 100, offset = 0) {
  try {
    const events = JSON.parse(localStorage.getItem(EVENTS_KEY) || '[]');
    return events.slice(offset, offset + limit);
  } catch {
    return [];
  }
}

/**
 * 获取事件统计
 */
export function getEventStats(range = 'day') {
  const events = getAllEvents();
  const now = Date.now();
  
  let startTime;
  switch (range) {
    case 'hour':
      startTime = now - 60 * 60 * 1000;
      break;
    case 'day':
      startTime = now - 24 * 60 * 60 * 1000;
      break;
    case 'week':
      startTime = now - 7 * 24 * 60 * 60 * 1000;
      break;
    case 'month':
      startTime = now - 30 * 24 * 60 * 60 * 1000;
      break;
    default:
      startTime = now - 24 * 60 * 60 * 1000;
  }
  
  const filtered = events.filter(e => e.timestamp >= startTime);
  
  // 按类型统计
  const byType = {};
  for (const event of filtered) {
    byType[event.type] = (byType[event.type] || 0) + 1;
  }
  
  // 按小时/天统计
  const byTime = {};
  for (const event of filtered) {
    let key;
    if (range === 'hour') {
      key = new Date(event.timestamp).toLocaleTimeString('zh-CN', { hour: '2-digit' });
    } else {
      key = new Date(event.timestamp).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' });
    }
    byTime[key] = (byTime[key] || 0) + 1;
  }
  
  return {
    total: filtered.length,
    byType,
    byTime,
    startTime,
    endTime: now
  };
}

/**
 * 获取工具使用趋势
 */
export function getToolUsageTrend(days = 7) {
  const usageStats = getUsageStats();
  const allEvents = getAllEvents();
  const now = Date.now();
  
  const trends = [];
  
  for (let i = days - 1; i >= 0; i--) {
    const dayStart = now - i * 24 * 60 * 60 * 1000;
    const dayEnd = dayStart + 24 * 60 * 60 * 1000;
    
    // 统计当日工具使用
    const dayEvents = allEvents.filter(e => 
      e.timestamp >= dayStart && 
      e.timestamp < dayEnd && 
      e.type === EventType.TOOL_USE
    );
    
    const toolCounts = {};
    for (const event of dayEvents) {
      const toolId = event.data.toolId;
      toolCounts[toolId] = (toolCounts[toolId] || 0) + 1;
    }
    
    trends.push({
      date: new Date(dayStart).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }),
      total: dayEvents.length,
      tools: toolCounts,
      topTool: Object.entries(toolCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || null
    });
  }
  
  return trends;
}

/**
 * 获取热力图数据 (小时 x 天)
 */
export function getHeatmapData() {
  const allEvents = getAllEvents();
  const heatmap = {};
  
  // 初始化 24小时 x 7天
  for (let hour = 0; hour < 24; hour++) {
    for (let day = 0; day < 7; day++) {
      const key = `${hour}:${day}`;
      heatmap[key] = 0;
    }
  }
  
  // 统计事件
  for (const event of allEvents) {
    const date = new Date(event.timestamp);
    const hour = date.getHours();
    const day = date.getDay();
    const key = `${hour}:${day}`;
    heatmap[key]++;
  }
  
  // 转换为数组格式
  const data = [];
  for (let hour = 0; hour < 24; hour++) {
    for (let day = 0; day < 7; day++) {
      const key = `${hour}:${day}`;
      data.push({
        hour,
        day,
        dayName: ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][day],
        hourLabel: hour.toString().padStart(2, '0') + ':00',
        count: heatmap[key],
        intensity: 0 // 0-1 normalized
      });
    }
  }
  
  // 计算强度
  const max = Math.max(...data.map(d => d.count), 1);
  for (const d of data) {
    d.intensity = d.count / max;
  }
  
  return data;
}

/**
 * 获取用户行为路径
 */
export function getUserPaths(steps = 5) {
  const allEvents = getAllEvents();
  const sessions = {};
  
  // 按session分组
  for (const event of allEvents) {
    if (!sessions[event.sessionId]) {
      sessions[event.sessionId] = [];
    }
    sessions[event.sessionId].push(event);
  }
  
  // 提取路径
  const paths = [];
  for (const sessionEvents of Object.values(sessions)) {
    sessionEvents.sort((a, b) => a.timestamp - b.timestamp);
    
    const path = sessionEvents.slice(0, steps).map(e => e.type);
    if (path.length >= 2) {
      paths.push(path.join(' → '));
    }
  }
  
  // 统计常见路径
  const pathCounts = {};
  for (const path of paths) {
    pathCounts[path] = (pathCounts[path] || 0) + 1;
  }
  
  return Object.entries(pathCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([path, count]) => ({ path, count }));
}

/**
 * 获取实时统计
 */
export function getRealtimeStats() {
  const allEvents = getAllEvents();
  const now = Date.now();
  
  // 最近5分钟事件
  const recent = allEvents.filter(e => now - e.timestamp < 5 * 60 * 1000);
  
  // 今日事件
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);
  const today = allEvents.filter(e => e.timestamp >= todayStart.getTime());
  
  // 昨日对比
  const yesterdayStart = new Date(todayStart);
  yesterdayStart.setDate(yesterdayStart.getDate() - 1);
  const yesterdayEnd = new Date(todayStart);
  const yesterday = allEvents.filter(e => 
    e.timestamp >= yesterdayStart.getTime() && 
    e.timestamp < yesterdayEnd.getTime()
  );
  
  return {
    online: recent.length, // 最近5分钟活动数作为"在线"指标
    todayTotal: today.length,
    yesterdayTotal: yesterday.length,
    change: yesterday.length > 0 ? 
      (((today.length - yesterday.length) / yesterday.length) * 100).toFixed(1) : 
      '0'
  };
}

// ============ 存储 ============

function getAllEvents() {
  try {
    return JSON.parse(localStorage.getItem(EVENTS_KEY) || '[]');
  } catch {
    return [];
  }
}

function saveEvents(events) {
  try {
    localStorage.setItem(EVENTS_KEY, JSON.stringify(events));
  } catch {
    // 清理后重试
    const trimmed = events.slice(-5000);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(trimmed));
  }
}

function restoreEvents() {
  try {
    const events = localStorage.getItem(EVENTS_KEY);
    if (events) {
      JSON.parse(events); // 验证格式
    }
  } catch {
    localStorage.removeItem(EVENTS_KEY);
  }
}

function cleanOldEvents() {
  const now = Date.now();
  const thirtyDays = 30 * 24 * 60 * 60 * 1000;
  
  const events = getAllEvents();
  const filtered = events.filter(e => now - e.timestamp < thirtyDays);
  
  if (filtered.length < events.length) {
    saveEvents(filtered);
    console.log(`[Analytics] Cleaned ${events.length - filtered.length} old events`);
  }
}

// ============ Session ============

let sessionId = null;

function getSessionId() {
  if (!sessionId) {
    sessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }
  return sessionId;
}

// 重置session（刷新页面后）
if (typeof window !== 'undefined') {
  window.addEventListener('beforeunload', () => {
    sessionId = null;
  });
}

export default {
  EventType,
  initAnalytics,
  trackEvent,
  getEvents,
  getEventStats,
  getToolUsageTrend,
  getHeatmapData,
  getUserPaths,
  getRealtimeStats
};